// C++98/03: Verbose and error-prone type declaration
template<typename It>
void process_range(It b, It e) {
    typename std::iterator_traits<It>::value_type val = *b;
    // ...
}

// C++11: `auto` is cleaner and safer
template<typename It>
void process_range_auto(It b, It e) {
    auto val = *b; // Correct type is deduced automatically
    // ...
}

// C++11: Handling unutterable lambda types
auto my_lambda = [](int x) { return x > 10; }; // OK
// std::function can store lambdas, but auto gets the *exact* type.
